def icon(name: str, *, size: int = 20, cls: str = "icon") -> str:
    """One inline SVG. Unknown names raise rather than rendering an empty box."""
    if name not in GLYPHS:
        raise KeyError(f"unknown icon {name!r}; have {', '.join(sorted(GLYPHS))}")
    return (
        f'<svg class="{cls}" width="{size}" height="{size}" viewBox="0 0 256 256" '
        f'fill="currentColor" aria-hidden="true" focusable="false">'
        f'{GLYPHS[name]}</svg>'
    )
